const output = ($json.output ?? '').toString();
const trimmed = output.trim();

let garbage = false;
let reason = null;

if (!trimmed) {
  garbage = true;
  reason = 'empty output';
} else if (/^\{\s*\}/.test(trimmed)) {
  garbage = true;
  reason = 'starts with empty JSON object';
} else if (/MCP error|Invalid arguments for tool/i.test(trimmed)) {
  garbage = true;
  reason = 'leaks a raw MCP tool error into the reply';
} else if (/MCP_Client_Tool|memory_recall\(|weather_get\(|skill_propose\(|calendar_event\(/.test(trimmed)) {
  garbage = true;
  reason = 'leaks internal tool/node name';
} else if (/"name"\s*:\s*"[^"]+"\s*,\s*"(parameters|arguments)"\s*:/i.test(trimmed)) {
  garbage = true;
  reason = 'contains a fake tool-call JSON blob';
} else if (/function call/i.test(trimmed)) {
  garbage = true;
  reason = 'narrates or describes a function call instead of making one';
} else if (/tool call (failed|fail)/i.test(trimmed)) {
  garbage = true;
  reason = 'narrates a failed tool call, violating the persona\'s "never mention tool failures" rule';
} else {
  // Confabulated-action check: a real, reproduced bug where the model claims
  // to have completed a write/action (created a goal, scheduled an event,
  // paused music, etc.) when no action-capable tool was even bound this turn
  // - e.g. a classifier hiccup left relevantTools empty/read-only, and the
  // model asserted success anyway instead of declining. Deterministic
  // backstop independent of any *specific* classifier bug - fires regardless
  // of why the action tool wasn't available this turn.
  const ACTION_TOOLS = ['goal_manage', 'calendar_event', 'spotify_control', 'dashboard_control', 'code_task', 'skill_propose', 'research_task'];
  const boundTools = $('Expand Groups To Tools').item.json.relevantTools ?? [];
  const hadActionTool = boundTools.some((t) => ACTION_TOOLS.includes(t));
  const claimsCompletedAction = /\b(?:I've|I have)\s+(added|noted|created|set\s?up|scheduled|deleted|removed|updated|started|paused|resumed|played|queued|turned)\b/i.test(trimmed)
    || /\b(?:has|have)\s+been\s+(added|noted|created|set\s?up|scheduled|deleted|removed|updated|started|paused|resumed|played|queued)\b/i.test(trimmed);
  if (!hadActionTool && claimsCompletedAction) {
    garbage = true;
    reason = 'claims a completed action but no action-capable tool was bound this turn (likely confabulated)';
  }
}

if (garbage) {
  console.log(`Detect Garbage Output: flagged (${reason}): ${trimmed.slice(0, 200)}`);
}

return { json: { ...$json, garbage, garbageReason: reason } };

function toText(content) {
  if (typeof content === 'string') return content;
  if (Array.isArray(content)) {
    return content
      .map((part) => {
        if (typeof part === 'string') return part;
        if (part && typeof part === 'object') return part.text ?? part.content ?? '';
        return '';
      })
      .join('');
  }
  if (content == null) return '';
  return String(content);
}

// alwaysOutputData on Fetch Recent History means a brand-new session with
// no prior rows still produces one item, but with no .message field at
// all — filter those out rather than crashing on undefined.
const rows = $input.all()
  .map(item => item.json.message)
  .filter(Boolean);
const reversed = [...rows].reverse();

const history = reversed
  .map(m => ({ role: m.type === 'human' ? 'user' : 'assistant', content: toText(m.content).trim() }))
  .filter(m => m.content.length > 0);

// No tools exist in this fallback path at all - the persona's own
// "never invent facts" rule assumes tools MIGHT be available this turn,
// which isn't true here, so it needs an explicit, unambiguous override:
// live testing found the model still confidently claiming to have
// searched/checked/logged something in this exact tool-free path (see
// docs/chat-workflow.md's 2026-09-20 entries) without this.
const fallbackSystemPrompt = $('Get Persona').first().json.system_prompt +
  '\n\nYou have no tools available for this specific response. Answer only from general ' +
  'knowledge and the conversation history above. If the question genuinely requires ' +
  'searching, checking, or logging something you have no way to do right now, say so ' +
  'honestly (e.g. "I\'m having trouble with that right now") - never claim to have ' +
  'searched, checked, found, or recorded something you did not actually do.';

const messages = [
  { role: 'system', content: fallbackSystemPrompt },
  ...history,
  { role: 'user', content: $('When chat message received').first().json.chatInput },
];

return [{ json: { messages } }];

const skills = $input.all().map(i => i.json).filter(s => s.name);
const text = skills.length
  ? skills.map(s => `## ${s.name}
${s.description}

${s.instructions}`).join('

')
  : '';
return [{ json: { skillsCatalogText: text } }];

const output = ($json.output ?? '').toString();
const trimmed = output.trim();
// Only worth checking (and worth the extra Ollama round trip) when a real
// capability tool was actually available this turn - a plain greeting/
// small-talk reply with only calculate bound has nothing to retry.
const relevantTools = ($('Expand Groups To Tools').first().json.relevantTools || []);
const hadCapabilityTool = relevantTools.some((t) => t !== 'calculate');
let alreadyRetried = false;
try {
  alreadyRetried = $('Prepare Search Retry Nudge').all().length > 0;
} catch (e) {
  // Prepare Search Retry Nudge has never run in this execution - first pass.
}
// Deliberately narrow: matches the specific "I'll/let me try again" pattern
// observed live, not every mention of the word 'search' - a broad match here
// would trigger a second full agent turn on ordinary replies too, which is
// wasted latency at best and a confusing extra message at worst.
const unfulfilledIntent =
  /\b(I['’]?ll|I will|let me|hold on|give me a (moment|second))\b[^.!?]{0,60}\b(try|search|look(ing)?|refin(e|ing)|check|find|research(ing)?)\b/i.test(
    output,
  );
// Genuinely empty output with a real tool available is a separate, real
// failure mode found via a live byte-capture investigation (see
// docs/chat-workflow.md's 2026-09-20 entries): qwen3:8b sometimes generates
// tokens for a specific tool combination that never resolve into either
// text or a parsed tool call (tool_calls.requested: 0), with zero error
// anywhere in the stack. A retry sometimes succeeds even though this
// doesn't fix the underlying model/Ollama-level grammar limitation.
const genuinelyEmpty = trimmed === '';
const shouldRetry = hadCapabilityTool && !alreadyRetried && (unfulfilledIntent || genuinelyEmpty);
if (shouldRetry) {
  console.log('Detect Unfulfilled Search Intent: flagged for retry:', genuinelyEmpty ? '(genuinely empty output)' : output.slice(0, 200));
}
return { json: { ...$json, shouldRetrySearch: shouldRetry } };
